window.GAAC_DATA = {"questions": [{"id": "insurance-enrollment", "category": "insurance", "title": "What has already improved in GA insurance enrollment?", "status": "Reported improvement", "answer": "More than 500 GAs were enrolled before fall began. Leadership reported a corrected DocuSign signing order and a single contact for insurance concerns. Those improvements happened before the November meeting; they do not mean every access problem is resolved.", "owner": "Student Affairs · insurance team", "next": "Investigate the remaining individual cases and finish clearer guidance.", "groups": [{"chapter": 1, "group": 0, "title": "Improvements acknowledged for fall 2026", "entries": [["Early enrollment", "More than 500 GAs were enrolled before the semester began. The accounts describe enrollment before August 14, ahead of an approximately August 30 semester start, with the aim of avoiding access gaps."], ["DocuSign order", "The signing order was corrected so that departmental approval was no longer a prerequisite for insurance enrollment."], ["One contact", "Jennifer was established as the single point of contact for insurance concerns, reducing uncertainty about whom a student should approach."]]}], "history": [["March 2023", "GAAC published an insurance explainer with links to cards, benefits and provider tools. Communication efforts predate this meeting.", "wisdom"], ["Spring 2026", "The insurance report proposed a process map, glossary, contacts, consolidated forms and a central information hub with May–July milestones. These were proposed deliverables, not proof they were completed.", "spring-ins"]], "quote": null, "now": "If enrollment still looks wrong, use the official insurance support route and keep your appointment and enrollment information available."}, {"id": "dental-vision", "category": "insurance", "title": "Why can’t I see or use my dental and vision benefits?", "status": "Follow-up needed", "answer": "Students described missing portal benefits, contradictory Aetna answers, expensive lenses and a provider declining the plan. The office said dental and vision were included and requested specific cases. The meeting did not verify every student’s benefits or resolve every case.", "owner": "Student Affairs · insurance team · Aetna", "next": "GAAC to collect affected cases; the insurance team to investigate and give Aetna feedback.", "groups": [{"chapter": 1, "group": 2, "title": "Benefits as described by the office", "entries": [["Mental health", "The response described care through Retriever Integrated Health as free and outside care as involving a copay. This records the explanation given, not a verification of every service, provider or student’s eligibility."], ["Dental and vision", "The office said both were included, while acknowledging that vision information was unclear on the website. Student accounts below showed that visibility, interpretation and access remained unresolved."], ["Dependents", "Whether dependent coverage is paid for was described as department-dependent. The discussion did not establish a universal employer-paid dependent benefit."]]}, {"chapter": 1, "group": 3, "title": "Student instances: retain each separately", "entries": [["Dental missing for full-time GAs", "Rishav reported that some full-time GAs saw dental in their Aetna portal while others did not. The office asked for affected students’ names or identifiable cases so staff could investigate and correct the records. The latest Detailed Talk checklist specifically says to collect those names and send them to Jennifer."], ["Vision missing and an incorrect telephone answer", "One attendee saw medical and dental but no vision in the portal. They called Aetna and were told they did not have vision, spent roughly three years believing that, and then discovered at an eye-care visit in the past year that a copay/vision benefit applied."], ["Exam discount and expensive lenses", "Another attendee described an eye exam priced at $75, reduced to $49 through Aetna, with more involved lenses costing over $150. They understood this as a discount rather than the expected coverage and questioned what the benefit actually provided."], ["Provider acceptance", "The same discussion included a report that a provider did not accept the student plan. This is a distinct access problem from whether a benefit is listed in the portal."], ["App versus browser", "An attendee’s app showed only dental, while the browser showed both cards. The accounts therefore identified inconsistent displays across access methods as well as confusion over the benefits themselves."]]}], "history": [["March 2023", "GAAC published an insurance explainer with links to cards, benefits and provider tools. Communication efforts predate this meeting.", "wisdom"], ["Spring 2026", "The insurance report proposed a process map, glossary, contacts, consolidated forms and a central information hub with May–July milestones. These were proposed deliverables, not proof they were completed.", "spring-ins"]], "quote": ["Meeting respondent", "If you have that person's name, if you can give it to me, um, so we can do a little bit more research on why it's not showing up for them, um, that would be helpful so that we can actually pinpoint it and fix the problem."], "now": "Use official plan information and individual support to confirm the service, provider and cost before relying on a meeting description."}, {"id": "insurance-plan", "category": "insurance", "title": "Will GAs have a say in the next insurance plan?", "status": "Participation supported", "answer": "Student participation in discussions with the final two or three prospective plans was supported. Late December or early spring was mentioned tentatively. No selection date or new benefit was promised.", "owner": "Student Affairs · insurance process participants", "next": "Notify GAAC when plan discussions are scheduled.", "groups": [{"chapter": 1, "group": 1, "title": "Question 1: Can GAAC review the next plan before it is selected?", "entries": [["Question and follow-up", "Could GAAC review both coverage and cost before the next insurance plan is chosen? How would dental, vision, dependent and mental-health concerns be considered in that decision?"], ["Response", "The office supported GAAC participation. It described the earlier practice of inviting students when the top two or three prospective plans came to campus to explain their offerings, and proposed using that approach again."], ["Timing", "Late December or early spring was mentioned tentatively. GAAC would be updated once the discussion was scheduled. No selection date, new benefit or change in coverage was promised."]]}], "history": [["March 2023", "GAAC published an insurance explainer with links to cards, benefits and provider tools. Communication efforts predate this meeting.", "wisdom"], ["Spring 2026", "The insurance report proposed a process map, glossary, contacts, consolidated forms and a central information hub with May–July milestones. These were proposed deliverables, not proof they were completed.", "spring-ins"]], "quote": null, "now": null}, {"id": "insurance-guidance", "category": "insurance", "title": "Will there be clearer insurance instructions and an Aetna session?", "status": "In progress", "answer": "Clearer website guidance, cards, educational materials and Aetna answers were discussed. An Aetna campus session was being arranged for February 2027. Two insurance/billing systems had been demonstrated; neither had been selected.", "owner": "Student Affairs · Aetna", "next": "Confirm the February session date; continue guidance and system assessment.", "groups": [{"chapter": 1, "group": 4, "title": "Responses, planned guidance and system assessment", "entries": [["Correct answers from Aetna", "The responding office acknowledged the need for Aetna to provide accurate answers when students call and said this feedback should be taken back to the insurer."], ["Website and educational materials", "Work with the insurance committee included clearer website information about coverage, where to find cards, presentations, and how-to guidance. Existing videos and glossaries, including resources useful to international students, were discussed. S2 describes how-to videos as planned; S1 also describes links to existing materials."], ["February information session", "An Aetna campus session for students to ask questions was being arranged for February. The date was still being worked out; the meeting did not establish that it had already occurred or that a final date was booked."], ["Two system demonstrations", "Student Affairs was assessing the insurance and billing process as a whole. It had recently seen two demonstrations, described in S3 as the previous week. One system was built for student health centers and might clarify timelines, charges and coverage internally, alongside Aetna’s own site."], ["Procurement status", "The next steps were to consider proposals and fit with the financial cycle. No system had been selected, funded or launched in the discussion."], ["What remained open", "Individual dental and vision discrepancies, provider acceptance, dependable instructions and the timing of student participation in plan review still required follow-through. The meeting did not establish that all students could see or use every benefit as described."]]}], "history": [["March 2023", "GAAC published an insurance explainer with links to cards, benefits and provider tools. Communication efforts predate this meeting.", "wisdom"], ["Spring 2026", "The insurance report proposed a process map, glossary, contacts, consolidated forms and a central information hub with May–July milestones. These were proposed deliverables, not proof they were completed.", "spring-ins"]], "quote": null, "now": null}, {"id": "insurance-gaps", "category": "insurance", "title": "Am I covered between December and January appointments?", "status": "Clarification needed", "answer": "The office said coverage should continue when a new appointment follows, but the department must complete the new form. The stated plan year was August 15, 2026–August 14, 2027. This did not settle cases without a succeeding appointment or replace requested written guidance.", "owner": "Student Affairs · appointing department", "next": "Provide written guidance and resolve individual gaps.", "groups": [{"chapter": 2, "group": 0, "title": "Question 2: What coverage applies during breaks and between contracts?", "entries": [["Main question", "Could Student Affairs provide clear written rules for breaks and the period between contracts? If an appointment ends before the next begins, what options would UMBC offer so the student is not uninsured?"], ["Dates given", "The plan period was described as August 15, 2026 through August 14, 2027. The enrollment window was stated as August 4 through September 15."], ["Administrative explanation", "The response said that a student’s apparent lack of immediate coverage often resulted from a department not yet submitting insurance paperwork. It distinguished such processing problems from an actual lapse, while acknowledging that students may not know where they stand."]]}, {"chapter": 2, "group": 1, "title": "Question 3: What about an appointment ending in December and restarting in January?", "entries": [["Specific instance", "Rishav raised semester-based contracts that end in early December, with the next spring offer beginning in January. He described students’ concern that the intervening period is not covered."], ["Response", "The response was that students with a new contract starting should still be covered, but departments must complete a new form. S2 attributes this explanation to Dr. Porter; the quotation-based account labels the speaker only as a respondent."], ["Important limit", "This was an explanation of how the process should operate. The discussion did not resolve every individual case, establish what happens without a succeeding appointment, or document a newly issued written rule."]]}], "history": [["Fall 2025 → spring 2026", "GAAC documented uncertainty about insurance between appointments; the spring deck asked for activation information and accountability.", "spring-deck"]], "quote": null, "now": "Ask the insurance office to confirm your individual coverage and ask your department whether the required form was submitted."}, {"id": "combined-forms", "category": "appointments", "title": "Will appointment, insurance and tuition forms be combined?", "status": "In development", "answer": "Offices are working with DoIT on a combined process so separate paperwork is less likely to be missed. Departmental reminders were discussed as an interim step. The combined process is not yet available to every GA.", "owner": "Graduate School · DoIT · partner offices", "next": "Continue development; clarify interim departmental reminders.", "groups": [{"chapter": 2, "group": 2, "title": "Preventing missed forms", "entries": [["Current weakness", "Appointment letters, insurance forms and tuition-remission paperwork were handled separately. A speaker said separate forms are easy for departments to overlook."], ["Unified process", "Participants described work with DoIT on a combined appointment-letter, insurance and tuition-remission process so the required elements can be handled together."], ["Interim reminders", "Renewal and submission reminders were proposed as a practical way to help departments while the combined process is still being developed."], ["Follow-through required", "The requested written guidance and case-specific resolution were not presented as completed. The combined process was still in development, not an operational fix that all students could already use."]]}], "history": [["December 2024", "The agenda called for clearer duties, work-hour expectations and appointment addenda.", "agenda24"], ["Spring 2026", "A standardized offer-letter template was proposed with a spring 2027 target.", "spring-gs"]], "quote": null, "now": null}, {"id": "housing-cost", "category": "campus", "title": "Will UMBC review on-campus housing costs for GAs?", "status": "Response promised", "answer": "Student Affairs agreed to explore on-campus affordability and return with a response at the April 15, 2027 Meet & Confer. Reduced GA rates require a separate discussion and have not been approved.", "owner": "Student Affairs", "next": "April 15, 2027: report what has been explored and possible options.", "groups": [{"chapter": 3, "group": 0, "title": "Question 4: Are on-campus rates affordable, and can UMBC explore a reduced GA rate?", "entries": [["Question and ownership", "The representative asked UMBC to assess whether on-campus housing is affordable on a GA stipend, explore a reduced rate, identify who would lead the review and specify when GAAC would receive a response."], ["Survey evidence presented", "50% of the 108 respondents were described as identifying housing as their biggest financial burden."], ["Cost illustration", "The example was approximately $1,200 per month for an on-campus bedroom or bed, compared with a $1,800-$2,000 monthly stipend. Speakers described rent as roughly 70% of that stipend. S2 calls the unit a one-bedroom; the other accounts say a bedroom or one bed. The report preserves the illustration without treating the unit description as settled."], ["Numerical qualification", "At the exact figures quoted, $1,200 is 60%-66.7% of $1,800-$2,000. The “roughly 70%” figure is retained as the meeting’s characterization rather than silently substituted as a calculated result."]]}, {"chapter": 3, "group": 1, "title": "Leadership response and commitment", "entries": [["Review versus reduction", "Housing fees are reviewed annually and apply across students. A special reduced rate would need a more detailed conversation beyond simply reviewing whether existing costs are affordable."], ["Affordability acknowledged", "The responding leader suggested that rates might well be unaffordable for GAs, but said the issue should be tested against data."], ["Lead and report back", "S2 identifies the Student Affairs leader as Dr. Kirsch and records a commitment to lead the affordability conversation. The leader agreed to return at the April 15 Meet & Confer with a response on what had been explored and possible options."], ["Limit of the commitment", "The leader could not promise the level of detail available by then. A reduced GA rate was not approved, and no implementation date or funding source was agreed."]]}, {"chapter": 3, "group": 2, "title": "Housing-demand study", "entries": [["Scope", "An ongoing study includes student focus groups, including graduate students; on-campus costs; nearby apartment-community costs; housing demand; and what students could afford if UMBC built additional housing or pursued local partnerships."], ["Timing", "The study might not be finished by April. The response offered to share any available insights at that time, rather than promising a completed study by the next meeting."], ["Open questions", "Affordability findings, possible reduced rates, other housing options and the practical response to the study remained outstanding."]]}], "history": [["2023", "GSA testimony linked rent and living costs to stipend adequacy. It did not establish a reduced on-campus GA rate.", "testimony"], ["May 2026", "The spring presentation raised on-campus affordability, availability and rate transparency.", "spring-deck"]], "quote": ["Student Affairs response", "I will lead the charge in starting the conversation and exploring the on-campus housing rates, whether they're affordable for GAs."], "now": null}, {"id": "stipend-review", "category": "pay", "title": "Will the stipend review lead to a pay increase?", "status": "Review planned", "answer": "A 1.5% increase to the minimum was reported as published in July. A further internal stipend review is expected to begin in spring 2027, with a possible late-summer share-out. A new increase or immediate budget change was not promised.", "owner": "Graduate School · colleges and departments", "next": "Begin the audit in spring; follow up on scope and expected reporting.", "groups": [{"chapter": 4, "group": 1, "title": "Cost-of-living increase and participation in fee decisions", "entries": [["1.5% increase", "Dr. Porter said the Graduate School had advocated for and secured a 1.5% cost-of-living increase. The updated minimum was published on the website in July. She acknowledged the modest size of the increase."], ["Fees outpacing support", "Rishav questioned whether the 1.5% adjustment kept pace with rising mandatory fees and housing costs. The broader concern was whether a GA could live adequately on the remaining income."], ["Graduate School at the table", "Dr. Porter said the Graduate School had not previously participated in fee conversations but would now be involved in future consultations. The exchange did not explain, reverse or reduce the existing fees."]]}, {"chapter": 5, "group": 0, "title": "Question 5: Will the stipend review account for actual living costs?", "entries": [["Question", "Representatives asked whether the review would consider housing, mandatory fees and insurance premiums, rather than only whether each department meets the formal stipend minimum."], ["Audit scope and start", "Dr. Porter described an internal review of UMBC graduate stipends across departments beginning in spring."], ["Expected reporting", "A report or share-out was unlikely before late summer. This was an expectation rather than an adopted delivery deadline."], ["Budget authority", "Departments and colleges control their budgets, which may already be set by the time findings are available. A review would therefore not necessarily produce an immediate pay increase."], ["Existing minimum", "Dr. Porter said departments must meet the current minimum and would have to meet a new minimum if it is increased."], ["Different net resources", "She acknowledged that the same nominal stipend leaves students in different positions when some must pay their own insurance. She supported continuing an honest conversation and putting the numbers before academic colleagues."], ["Not settled", "No new stipend minimum, specific cost-of-living formula, automatic adjustment mechanism or increase date was promised."]]}], "history": [["2023", "GSA testimony described stipends falling short of living costs and housing expenses. These are historical concerns, not current pay rates.", "testimony"], ["Spring 2026", "The written report targeted a stipend review during summer/fall 2026 and completion by spring 2027.", "spring-gs"]], "quote": ["Dr. Christa Porter", "We probably won't have a report or any sort of share-out until late summer."], "now": null}, {"id": "fees-workload", "category": "pay", "title": "What is happening about fees, unequal costs and workload?", "status": "Still unresolved", "answer": "Students raised rising fees, different insurance costs and unequal duties. The Graduate School committed to participate in future fee conversations. No fee reduction, workload adjustment or resolution of department-level disparities was agreed.", "owner": "Graduate School · colleges · departments", "next": "Seek an explanation of fee differences, review progress and how GA input affects decisions.", "groups": [{"chapter": 4, "group": 0, "title": "Concerns and concrete comparisons", "entries": [["Mandatory fees", "Approximately 74% of respondents were said to consider mandatory fees too high and rising each year. The quotation-based account preserves the speaker saying “75% or 74%.” Representatives described GAs as living paycheck to paycheck."], ["Unequal insurance support", "Some half-GAs and students dividing their work between part-time RA and TA appointments reportedly did not receive the same benefit as other GAs. A figure of about 40% paying premiums out of pocket was presented; the supplied accounts do not establish that figure’s exact denominator."], ["Late first paycheck", "Some GAs did not receive their first paycheck on time that semester. The record does not establish how many, identify individual cases or document a guaranteed payroll remedy."], ["Workload differences", "Representatives contrasted remote TA work with roles requiring campus attendance, including an example of two classes per week rather than one. They questioned whether differences in duties and workload were reflected in stipends or support. No new workload standard or adjustment was agreed."]]}], "history": [["December 2024", "The agenda raised differing program fees, bills arriving before pay and the adequacy of stipends.", "agenda24"], ["Spring 2026", "The Graduate School proposed stronger participation in fee review and clearer explanations of costs.", "spring-gs"]], "quote": null, "now": null}, {"id": "universal-insurance", "category": "insurance", "title": "Will every GA receive the same minimum insurance benefit?", "status": "Still unresolved", "answer": "GAAC asked for a minimum benefit across appointments, including half and split RA/TA appointments. Dr. Porter supported the aim but said funding constraints could reduce the number of positions if a more costly package were required. Universal coverage was not approved.", "owner": "Graduate School · colleges and departments", "next": "Continue the benefits-and-budget discussion; obtain clear eligibility guidance.", "groups": [{"chapter": 5, "group": 1, "title": "Question 6: Could every GA receive a minimum insurance benefit?", "entries": [["Question", "Could UMBC establish a minimum insurance benefit across GA appointments rather than leaving support to the department? The examples included half appointments and split RA/TA work."], ["Response", "Dr. Porter said she had advocated for the goal, but described insurance, stipend and tuition as a nuanced budget question."], ["Trade-off stated", "If departmental funding remains flat, requiring a more expensive package for every GA could reduce the number of GA positions."], ["Not settled", "Agreement with the aim did not amount to approval of universal coverage or a commitment to additional departmental funding."]]}], "history": [["Fall 2025 → spring 2026", "GAAC documented uncertainty about insurance between appointments; the spring deck asked for activation information and accountability.", "spring-deck"]], "quote": null, "now": null}, {"id": "pay-bridge", "category": "pay", "title": "Could an interest-free Pay Bridge help when pay is interrupted?", "status": "Under review", "answer": "A bridge was requested for pay or funding gaps. The Graduate School is consulting General Counsel and Financial Aid and looking at peer institutions. No program, interest rate, fees, eligibility or repayment terms have been approved.", "owner": "Graduate School · General Counsel · Financial Aid", "next": "A clearer update is expected in spring 2027; peer loan interest rates still need checking.", "groups": [{"chapter": 5, "group": 2, "title": "Question 7: Could a pay bridge provide an interest-free loan during gaps?", "entries": [["Question", "Representatives asked about an interest-free loan or similar bridge when pay or funding stops between appointments, or when funding is cut between semesters."], ["Legal and financial review", "Dr. Porter said the Graduate School was consulting General Counsel and Financial Aid about implications, including tax consequences and differences affecting international and domestic students. The stated goal was to avoid creating harm for recipients."], ["Benchmarking", "Other institutions’ approaches were being examined. S1 identifies Cheryl as doing that benchmarking; the role and spelling are not independently verified here."], ["Expected update", "Dr. Porter expected a clearer sense in spring. The idea was still under review; no loan program had been approved or launched."]]}, {"chapter": 5, "group": 3, "title": "Question 8: Are peer institutions’ loans interest-free or lower-interest?", "entries": [["Follow-up", "A representative specifically asked whether the institutions being benchmarked offered zero interest or simply a lower rate."], ["Answer", "Dr. Porter said she did not yet know and would check."], ["Open terms", "The meeting did not establish an interest rate, fees, eligibility, amount, repayment schedule or approval process. The synopsis phrase “interest-free loan” describes the request, not an approved feature."]]}], "history": [["Spring 2026", "The Graduate School report explored a Pay Bridge for delayed first pay, funding changes and other interruptions.", "spring-gs"]], "quote": ["Dr. Christa Porter", "I'm not sure. I can check that out though."], "now": "Do not plan around Pay Bridge being available. Use the Graduate School’s official contact route to ask about current options for your situation."}, {"id": "late-pay", "category": "pay", "title": "Has the problem of delayed first paychecks been solved?", "status": "Still unresolved", "answer": "Delayed first paychecks were raised again in November. The record does not establish a guaranteed immediate payment mechanism or that all payroll issues have been resolved. Pay Bridge and combined paperwork are separate development efforts.", "owner": "Appointing department · payroll support · Graduate School", "next": "Follow up on the individual interruption and the longer-term process work.", "groups": [{"chapter": 4, "group": 0, "title": "Concerns and concrete comparisons", "entries": [["Mandatory fees", "Approximately 74% of respondents were said to consider mandatory fees too high and rising each year. The quotation-based account preserves the speaker saying “75% or 74%.” Representatives described GAs as living paycheck to paycheck."], ["Unequal insurance support", "Some half-GAs and students dividing their work between part-time RA and TA appointments reportedly did not receive the same benefit as other GAs. A figure of about 40% paying premiums out of pocket was presented; the supplied accounts do not establish that figure’s exact denominator."], ["Late first paycheck", "Some GAs did not receive their first paycheck on time that semester. The record does not establish how many, identify individual cases or document a guaranteed payroll remedy."], ["Workload differences", "Representatives contrasted remote TA work with roles requiring campus attendance, including an example of two classes per week rather than one. They questioned whether differences in duties and workload were reflected in stipends or support. No new workload standard or adjustment was agreed."]]}], "history": [["Fall 2022, reported in 2023", "GSA testimony reported students going weeks or months without pay during the preceding fall. It also said Meet & Confer had resumed in fall 2022 after a gap.", "testimony"], ["March 2026", "GAAC publicly reported continuing work on appointment and payroll processes after the December 2025 meeting.", "advocacy"]], "quote": null, "now": "Start with your appointing department’s business/payroll contact. If the problem persists, contact the Graduate School with the dates and appointment details."}, {"id": "emergency-support", "category": "support", "title": "What emergency financial or housing support was discussed?", "status": "Mixed progress", "answer": "Three different supports were discussed: widening of the Graduate Student Emergency Fund; a separate all-student fund still being developed; and an established Maritime Conference Center partnership for emergency housing. Current award amounts and access arrangements were not established at the meeting.", "owner": "Graduate School · Dean of Students", "next": "Confirm eligibility and access directly; a spring update on the all-student fund was hoped for.", "groups": [{"chapter": 4, "group": 2, "title": "Three different emergency-support mechanisms", "entries": [["Graduate Student Emergency Fund", "Dr. Porter said the fund had been widened somewhat, acknowledged that the money was limited and expressed an intention to increase support. The accounts do not specify the amount, award size, revised eligibility, application route or guaranteed assistance for a particular student."], ["Dean of Students emergency fund", "A separate fund for all students was being developed through the Dean of Students Office following generous donations. Staff were still working through the process and hoped to share more in spring. It should not be merged with the graduate-specific fund in reporting."], ["Emergency housing", "A partnership with the Maritime Conference Center, described as a full facility with dining, had been established. The response said support would be made available for true emergency housing needs; operating details and current access were not confirmed."], ["Limits", "These supports were discussed as emergency assistance. They did not settle the underlying stipend, fee, ongoing housing-affordability or universal insurance questions."]]}], "history": [["Spring 2026", "The Graduate School report proposed increasing the availability of emergency-fund support.", "spring-gs"]], "quote": ["Dr. Christa Porter", "The Graduate Student Emergency Fund, I am happy to share that we are able to widen it a bit."], "now": "Contact the Graduate School for graduate-specific support or the Dean of Students for broader student support. Ask what is currently available; assistance is not guaranteed."}, {"id": "appointment-template", "category": "appointments", "title": "What will change in the new GA appointment letter?", "status": "In development", "answer": "The revised template is intended to state duties, communication expectations, stipend, benefits and departmental requirements more clearly. Additional GPD feedback is due December 2. A summer soft launch and fall 2027 use were discussed, initially for new GAs.", "owner": "Graduate School · GPDs · DoIT", "next": "December 2, 2026: additional feedback; summer/fall 2027: rollout goal.", "groups": [{"chapter": 6, "group": 0, "title": "Revised appointment template", "entries": [["Consultation", "Dr. Porter reported consultation with graduate program directors, some department chairs and students, and planned contact with deans. She thanked students for their involvement."], ["What the document would contain", "The template would set out expectations, communication strategies and arrangements, stipend and benefits, and additional departmental or supervisory requirements. S1 also records signatures from the GA and supervisor."], ["Feedback deadline", "Graduate program directors had until December 2 to submit additional comments. DoIT work on the process would follow."], ["Schedule change", "An earlier spring launch goal had shifted to a summer soft launch, with the discussion pointing toward fall 2027 use. Dr. Porter explained that due diligence, consultation and implementation were taking longer than hoped."], ["Initial coverage", "The initial rollout would apply to new GAs. Requiring departments and chairs to redo documentation for all existing GAs at once - described in the discussion as about 600 students - would be a substantial workload."], ["Status", "The desired outcome was a clearer, unified electronic appointment process. It was not described as already operational for all GAs."]]}], "history": [["December 2024", "The agenda called for clearer duties, work-hour expectations and appointment addenda.", "agenda24"], ["Spring 2026", "A standardized offer-letter template was proposed with a spring 2027 target.", "spring-gs"]], "quote": ["Dr. Christa Porter", "We're giving graduate program directors until December 2nd to give us any additional feedback."], "now": null}, {"id": "renewal-notice", "category": "appointments", "title": "What if my department misses an applicable renewal-notice deadline?", "status": "Intervention offered", "answer": "Where the 60-day guidance applies, Dr. Porter said students should contact the Graduate School. She would follow up with the department; discontinued grant funding was an example of a possible exception. No automatic penalty, compensation or guaranteed renewal was specified.", "owner": "Graduate School · appointing department", "next": "Send reminders and follow up on missing notice reported by students.", "groups": [{"chapter": 6, "group": 1, "title": "Question 9: What justifies less than 60 days’ notice, and what happens if a department misses it?", "entries": [["Question", "Where the 60-day guidance applies, what counts as a valid reason for shorter notice? What would the Graduate School do if a department misses the deadline without a valid reason?"], ["Possible exception", "Dr. Porter gave discontinued funding, such as a grant ending or no longer being available, as an example of a valid reason. She emphasized that there were not many valid reasons for missing notice."], ["Intervention", "She said she would contact the department or the person missing the deadline. No automatic penalty, guaranteed renewal or compensation for missed notice was specified."], ["Reminders and example", "The Graduate School would send reminders. An August 15 appointment start was used to illustrate a reminder date around June 16."], ["Question 10: Should the student report missing notice?", "When a representative asked whether students should contact the Graduate School if they do not receive follow-up, Dr. Porter answered yes, emphatically. Students were not told to assume the Graduate School already knows."]]}], "history": [["Fall 2025 → March 2026", "GAAC reported late renewals and funding uncertainty, and joined the GA Lifecycle Working Group.", "advocacy"], ["Spring 2026", "The Graduate School considered reminders, clearer expectations and a nonrenewal notification template.", "spring-gs"]], "quote": ["Dr. Christa Porter", "Oh, contact us. Absolutely. Yes, please."], "now": "Contact the Graduate School rather than assuming it already knows notice is missing."}, {"id": "semester-notice", "category": "appointments", "title": "How much notice should a semester-only GA receive?", "status": "Still unresolved", "answer": "This was not settled. After a representative pointed out the longer-than-one-semester clause, Dr. Porter agreed to examine it. The initial response in the room should not be presented as a definitive rule for semester-only appointments.", "owner": "Graduate School", "next": "Clarify the applicable rule and whether a minimum notice period needs to be established.", "groups": [{"chapter": 6, "group": 2, "title": "Question 11: What notice should a semester-only GA receive?", "entries": [["Question", "How far in advance should someone hired for one semester learn whether they will be renewed? Could UMBC set a clear minimum so students can plan finances and housing?"], ["Initial response", "Dr. Porter said the 60-day rule comes from USM, not a UMBC-created rule, and initially said she did not think it distinguished semester appointments from nine- or twelve-month appointments."], ["Clarification in the room", "A representative pointed to language applying the 60 days to contracts longer than a semester. Dr. Porter acknowledged the clause and said she would examine the issue further and what needed to be established."], ["Unresolved outcome", "No minimum notice period for semester-only GAs was settled. This report records that unresolved exchange rather than converting the initial response into a definitive policy interpretation."]]}], "history": [["Fall 2025 → March 2026", "GAAC reported late renewals and funding uncertainty, and joined the GA Lifecycle Working Group.", "advocacy"], ["Spring 2026", "The Graduate School considered reminders, clearer expectations and a nonrenewal notification template.", "spring-gs"]], "quote": null, "now": null}, {"id": "funding-complaint", "category": "voice", "title": "Who can I contact if a supervisor concern puts my funding at risk?", "status": "Support route identified", "answer": "Dr. Porter said to contact the Graduate School directly. It can consider mediation or another review process. Students need not go through a supervisor or GPD involved in the concern when they do not feel comfortable doing so.", "owner": "Graduate School", "next": "Clarify the written route, review steps and available remedies.", "groups": [{"chapter": 7, "group": 0, "title": "Question 12: Who outside the department reviews funding loss after a complaint?", "entries": [["Question", "If a GA raises a concern about a supervisor and then loses funding, how would someone outside the department determine whether the events are connected? What support would the GA receive during that review?"], ["Immediate route", "Dr. Porter instructed students to contact the Graduate School about a funding loss or supervisor concern."], ["Contact identified", "The supplied accounts name Associate Dean “Rodney Couvert” as the person receiving such concerns. That is transcript-derived wording; the official spelling and contact details should be checked before the name is used as a referral."], ["Review process", "The Graduate School could use its mediation process or decide whether a separate committee was appropriate. The meeting did not establish an automatic outside committee, a finding of retaliation in a particular case, or a standard remedy for all funding losses."]]}, {"chapter": 7, "group": 3, "title": "Clearer guidance and routes", "entries": [["Handbook revision", "Dr. Porter said the GA handbook was being revised. A grievance chart, clearer website guidance and more explicit handbook language were discussed as ways to make the process understandable."], ["Certainty of the chart", "S2 says a chart and clearer pathway will be added; S1 and S3 frame a chart as one possible way to improve clarity. The reliable common point is that revision and clearer communication were discussed, while the final format was not established in the quotation-based account."], ["Student Affairs communication", "Student Affairs offered to link to Graduate School resources and tell students where to go through its own website. A newsletter after Meet & Confer was suggested, including the most useful outcomes and contact routes."], ["College-level options", "Dr. Porter encouraged students to approach a dean, associate dean, assistant dean or department chair when appropriate."], ["Direct Graduate School access", "She explicitly recognized that an advisor, supervisor or graduate program director may be involved in the concern. Where trust or comfort is lacking, students should come directly to the Graduate School; college-level contact was not presented as an absolute prerequisite."], ["Sharing the information", "The accounts discuss communicating outcomes in January and through a March town hall so students know what changed and how to seek help."]]}], "history": [["December 2024", "The agenda asked for clearer retaliation reporting, anonymous options and transparent complaint follow-up. These were requests.", "agenda24"], ["May 2026", "The spring presentation raised mentorship feedback and clearer routes for concerns.", "spring-deck"]], "quote": ["Dr. Christa Porter", "If they lose their funding, one, contact us. If there's any concerns with supervisors, contact us. Period."], "now": "Use the Graduate School’s official directory to reach the appropriate office. The associate dean’s name is unclear in the supplied transcript, so this guide does not repeat it as a verified referral."}, {"id": "mediation-pay", "category": "voice", "title": "What did leadership say about pay and removal during mediation?", "status": "Assurance at meeting", "answer": "Dr. Porter said departments had been told not to proceed with removal during the Graduate School process and that students should continue being paid and performing duties. A complete written procedure covering every circumstance was not supplied. An automatic substitute TA appointment was not approved.", "owner": "Graduate School · appointing department", "next": "Publish a clear procedure and explain how students can obtain urgent case-specific help.", "groups": [{"chapter": 7, "group": 1, "title": "Question 13: What protects the student’s income and appointment during the process?", "entries": [["Rishav’s concern", "The handbook mentions retaliation but does not show a clear pathway: where to go, what happens after a report and how a review works. Students need to understand the route before they can confidently use it."], ["Concrete support request", "Rishav asked whether a student whose RA appointment is cancelled could receive a TA appointment or a pay bridge so the student does not suddenly lose all financial support. No automatic substitute TA appointment or bridge entitlement was approved."], ["Protection described by Dr. Porter", "Departments had been told not to move forward with removal while the Graduate School process is playing out. She said the student should continue being paid, performing duties and remaining in the appointment during that process."], ["Limits of this record", "The statements were assurances made at the meeting. The accounts do not supply a complete written procedure covering every funding source, case type, duration, appeal or emergency intervention."]]}, {"chapter": 7, "group": 2, "title": "International students’ fears: concerns reported, not adjudicated cases", "entries": [["Fear of speaking", "A representative said international students were scared to raise concerns and had been advised by others to keep quiet because nothing would happen."], ["Fear of losing opportunities", "Students worried that a complaint could damage the advisor relationship, cause a grant or funding to be cancelled, or lead other departments to blacklist them or withhold another appointment."], ["Status of the examples", "These statements describe fears and reported experiences voiced in the discussion. The meeting did not establish findings against a named department or supervisor."]]}], "history": [["December 2024", "The agenda asked for clearer retaliation reporting, anonymous options and transparent complaint follow-up. These were requests.", "agenda24"], ["May 2026", "The spring presentation raised mentorship feedback and clearer routes for concerns.", "spring-deck"]], "quote": ["Dr. Christa Porter", "The student, you should still get paid, you should still be doing your duties, you should still be doing the things while the grad school is working out the process."], "now": null}, {"id": "president-retaliation", "category": "voice", "title": "What did the president say about retaliation and speaking up?", "status": "Assurance at meeting", "answer": "The president rejected retaliation, recognized how difficult it can be for students to raise concerns and described the university’s responsibility to protect students. These assurances matter; the operational reporting and review instructions still need to be clear.", "owner": "President · Provost · Graduate School", "next": "Make the reassurance visible alongside practical routes for help.", "groups": [{"chapter": 8, "group": 0, "title": "Institutional assurance on retaliation", "entries": [["Position", "The president said retaliation is unacceptable and that the university has a responsibility to protect students when raising an inappropriate experience leads to retaliation."], ["International students", "The remarks explicitly addressed students regardless of where they come from. They rejected the idea that the surrounding political or federal context removes students’ human rights or the university’s responsibility to respond."], ["Leadership involvement", "The accounts describe the Graduate School, provost and president acting when concerns reach them. The president acknowledged that it is easier for leadership to say “don’t be afraid” than it is to be the student facing the risk."], ["Representative excerpt", "“Be confident that your university Has your back on that, right? It really does.” [S3]"], ["Meaning and limit", "These were institutional assurances, not a complete operational grievance policy or a promise that a particular remedy would apply in every case. The need for clearer reporting and review instructions remained."]]}, {"chapter": 8, "group": 1, "title": "Transcript problem that must stay visible", "entries": [["Conflicting opening sentence", "S1 reproduces a visibly corrupted opening that appears to call retaliation acceptable, then immediately explains that the next statements reject it. S2 renders that opening with “not acceptable.” S3 avoids quoting the corrupted sentence and provides the surrounding clear statements."], ["Editorial treatment", "This report does not turn either version into a verified standalone quotation. The clear rejection is summarized above; all supplied wording remains available in the documentary appendices with this warning."]]}], "history": [["December 2024", "The agenda asked for clearer retaliation reporting, anonymous options and transparent complaint follow-up. These were requests.", "agenda24"], ["May 2026", "The spring presentation raised mentorship feedback and clearer routes for concerns.", "spring-deck"]], "quote": ["UMBC president · supplied quotation-based account", "Be confident that your university Has your back on that, right? It really does."], "now": null}, {"id": "leave", "category": "support", "title": "What are the rules for leave and bereavement?", "status": "Clarification needed", "answer": "GAAC raised unclear leave and bereavement guidance, especially for year-long appointments. The response acknowledged a need for clarity and discussed work with General Counsel. No new allowance, number of days or approval process was adopted.", "owner": "Graduate School · General Counsel", "next": "GAAC to provide examples of how departments handle requests; seek clearer written guidance.", "groups": [{"chapter": 10, "group": 0, "title": "Question 17: Can leave and bereavement rules be clarified?", "entries": [["Problem", "Rishav said GAs on a one-year contract lacked a clear leave and bereavement policy. The response acknowledged that the handbook is unclear; it did not establish that no relevant protection of any kind exists."], ["Response", "The Graduate School would consider clearer guidance and work with General Counsel. S2 describes this as a commitment; the quotation-based account phrases it as work to consider."], ["Request to GAAC", "Officials asked for concrete examples of how requests arise and how different departments handle them so the problem can be understood in practice."], ["Open outcome", "No new leave entitlement, number of days, bereavement allowance, approval process or interim rule was agreed."]]}], "history": [], "quote": null, "now": "Ask your department and the Graduate School about your situation. The meeting’s uncertainty is not evidence that no existing protections apply."}, {"id": "workspace", "category": "campus", "title": "Who is addressing crowded offices and shared lab space?", "status": "Follow-up discussed", "answer": "Crowded shared labs and workspace concerns were raised. Leadership described work with deans on space utilization and offered follow-up. No new GA allocation, relocation or completion date was agreed.", "owner": "Academic leadership · college deans · departments", "next": "Follow up on concrete workspace needs and the wider space review.", "groups": [{"chapter": 10, "group": 1, "title": "Question 18: Who can address office and lab-space shortages?", "entries": [["Student experience", "Rishav described crowded shared computer-science labs and multiple faculty/lab groups sharing space in the college rendered as “COIT” in S3."], ["Specific, unverified instance", "He relayed that a newly hired CS professor reportedly lacked an assigned lab and explicitly said, “don’t quote me on this.” The response referred to an office. The account does not establish the faculty member’s actual assignment or whether the issue concerns a lab, office or both."], ["Response and follow-up", "A leader said the reported absence of faculty space was concerning and that they would follow up. S2 attributes that response to Dr. Kirsch; S1/S3 do not reliably identify the speaker."], ["Broader review", "The university was stepping back with deans to assess space utilization, particularly while hiring faculty. Students were encouraged to identify exact pain points to departments and colleges."], ["Sherman 2", "S1 says Sherman 2 was “coming along”; S2 calls construction on schedule. Neither establishes an immediate workspace solution for a particular GA."], ["Open outcome", "No GA workspace allocation, relocation, capacity target or completion date was agreed."]]}], "history": [["May 2026", "GA workspace was raised as a concern in the spring Meet & Confer presentation.", "spring-deck"]], "quote": null, "now": null}, {"id": "parking", "category": "campus", "title": "What happens next on parking and transportation concerns?", "status": "Discussion proposed", "answer": "Students described difficulty finding parking despite holding permits. A dedicated discussion with parking and transportation representatives was recommended, with Student Affairs/GSA helping make connections. No service change or meeting date was agreed.", "owner": "Parking and transportation offices · Student Affairs · GSA", "next": "Arrange a focused meeting and bring concrete access and schedule examples.", "groups": [{"chapter": 10, "group": 2, "title": "Question 19: Who can organize a focused parking and transportation discussion?", "entries": [["Problem", "GAs reported difficulty finding parking even when they had paid for a permit; the quoted account renders this as a “parking ticket.” Transportation concerns were also raised."], ["Suggested approach", "The response recommended a dedicated meeting on this topic rather than treating it as a small item in a broader agenda. It should examine the reasons for schedule or service changes as well as the complaints."], ["Potential participants", "S1/S2 name Daniel Teach as an administrator interested in speaking with students; Gina, described as overseeing parking, could also join. Saad or Student Affairs could help connect the group."], ["Prior contact differs in wording", "S1/S3 describe a Daniel-Saad conversation; S2 describes Daniel already speaking with the relevant administrator. The clear follow-up is to arrange the focused conversation, not to assume the exact chain of prior introductions is settled."], ["Existing channel", "An existing student advisory board was mentioned as relevant to the discussion."], ["Open outcome", "No meeting date, parking-space change, permit remedy or transit schedule change was agreed."]]}], "history": [], "quote": null, "now": null}, {"id": "immigration", "category": "campus", "title": "Can urgent immigration or CPT/OPT issues be resolved faster?", "status": "Staffing update", "answer": "Leadership reported that the understaffed office was adding staff after a summer with about 2,000 tickets for two people. This was not a guarantee that delays were resolved. No urgent-case response target or new escalation mechanism was promised.", "owner": "International student advising · Global Engagement", "next": "Follow staffing progress and request a clearly documented urgent-case route.", "groups": [{"chapter": 10, "group": 3, "title": "Question 20: How can urgent immigration and ISSS delays be addressed?", "entries": [["Problem", "Rishav reported delays in ISSS responses, including time-sensitive immigration requests. CPT/OPT advising uncertainty was part of the wider concern."], ["Capacity explanation", "The responding official described the office as understaffed, with about 2,000 tickets received or handled by two people over two summer months."], ["Staffing response", "Additional staff were being hired that semester, which officials expected to improve response times. This was a staffing update, not evidence that the backlog had already been cleared."], ["Rules and uncertainty", "S1 links advising difficulty to changing or proposed rules and uncertainty about what advice to give. S2 says expected CPT/OPT ruling changes could reduce uncertainty and workload. Neither supplies a specific rule, implementation date or verified regulatory outcome."], ["Open outcome", "No urgent-case escalation contact, guaranteed quick-resolution mechanism or specific ticket-response target was promised."]]}], "history": [], "quote": null, "now": "Use the official international-student contact page for tickets and current advising options. That office currently uses the name Office of International Students and Scholars; older records say ISSS."}, {"id": "early-input", "category": "process", "title": "Will GAAC be involved before decisions are made?", "status": "Participation supported", "answer": "Officials pointed to GAAC’s involvement in the appointment-template workgroup as a model for future decisions. Earlier student participation was supported; a new standing committee, consultation deadline or formal decision right was not established.", "owner": "GAAC · Graduate School · relevant offices", "next": "Track whether students are included early enough to shape proposals.", "groups": [{"chapter": 9, "group": 0, "title": "Question 14: How can GAAC be involved before decisions are effectively made?", "entries": [["Question", "How can GAAC participate early in decisions affecting appointments and pay, alongside the administration?"], ["Response", "The appointment-template workgroup was cited as an example of involving GAAC while a proposal is being developed. Officials said that model could be used in future decisions and emphasized the importance of having students at the table."], ["Limit", "No new standing committee, consultation deadline or formal decision right was established in the supplied accounts."]]}], "history": [["2023, reflecting on 2022", "GSA testimony argued that the existing process did not adequately capture or resolve concerns. This is a historical student account, not a claim about current legal requirements.", "testimony"], ["March 2026", "GAAC published a progress update connecting student concerns to workgroups and upcoming discussions.", "advocacy"]], "quote": null, "now": null}, {"id": "decision-reasons", "category": "process", "title": "Will written updates explain how student input was used?", "status": "Follow-up promised", "answer": "GAAC asked for the reasoning behind decisions and how GA input was considered. The synopses describe agreement to improve explanation; the quotation-based account preserves only a brief affirmative response.", "owner": "Graduate School · Student Affairs", "next": "Look for explanations and responses to the actual questions in the December reports.", "groups": [{"chapter": 9, "group": 1, "title": "Question 15: Will written updates explain the reasoning and how GA input was used?", "entries": [["Question", "Could future written updates explain how GA input was considered or implemented and why a decision was made? Daniel emphasized that students want to understand the process, not just see an outcome."], ["Response across sources", "S1 and S2 describe agreement to improve explanation, with S2 attributing it to Dr. Porter and Dr. Kirsch. S3 preserves only a brief affirmative response, “Okay, great.” The report records the requested reporting practice and the summarized agreement without inventing a detailed explanation that was not supplied."]]}], "history": [["2023, reflecting on 2022", "GSA testimony argued that the existing process did not adequately capture or resolve concerns. This is a historical student account, not a claim about current legal requirements.", "testimony"], ["March 2026", "GAAC published a progress update connecting student concerns to workgroups and upcoming discussions.", "advocacy"]], "quote": null, "now": null}, {"id": "next-updates", "category": "process", "title": "When will we receive written answers and meet again?", "status": "Dates recorded", "answer": "The agreed sequence was a summary within about one week of November 18, office responses by December 18, and January communication to GAs. April 15, 2027 is the next Meet & Confer date. March town-hall communication was also mentioned without a fixed day.", "owner": "GAAC · Graduate School · Student Affairs", "next": "December 18: written office responses. April 15: next Meet & Confer.", "groups": [{"chapter": 9, "group": 2, "title": "Question 16: Who will maintain a shared record, and when will people hear back?", "entries": [["Question", "Daniel asked about a shared action record identifying the obligations accepted by different offices and when GAAC and the wider GA community would receive updates."], ["Agreed sequence", "Rishav proposed a summary within about one week of November 18, written Graduate School and Student Affairs responses by December 18, and sharing results with GAs in January. The exchange recorded assent."], ["Who does what", "The supplied action list assigns the post-meeting summary and student communication to Rishav/GAAC and written office reports to the Graduate School and Student Affairs. The latest Detailed Talk checklist explicitly adds preparing the January town-hall report using the December 18 office responses, following up on spring pay-bridge and stipend-audit timelines, and preparing the April 15 agenda. It does not designate a separate administrator for a shared tracking system."], ["Next meeting", "Rishav confirmed April 15 as the next Meet & Confer and said the calendar invitation had already been shared."], ["Spring reporting", "Participants asked about spring and discussed a similar reporting interval after the spring meeting. No spring written-report date was specified; this document does not invent one."], ["Communication formats", "S2 calls January sharing a town hall; S1 and S3 describe January reporting and subsequent town-hall communication, with March also mentioned. Both references are preserved as recorded rather than assuming a single confirmed town-hall date."]]}], "history": [["2023, reflecting on 2022", "GSA testimony argued that the existing process did not adequately capture or resolve concerns. This is a historical student account, not a claim about current legal requirements.", "testimony"], ["March 2026", "GAAC published a progress update connecting student concerns to workgroups and upcoming discussions.", "advocacy"]], "quote": null, "now": null}, {"id": "meeting-context", "category": "process", "title": "Who participated, what was raised and how should I read this record?", "status": "Meeting record", "answer": "The meeting brought GA representatives and university leadership together around insurance, housing, pay, fees, appointments, speaking up and additional concerns. It produced explanations and follow-ups, alongside issues still unresolved. Survey figures spoken in the meeting are not a fresh analysis of the underlying data.", "owner": "GAAC · participating university offices", "next": "Track the follow-ups rather than treating discussion alone as a completed solution.", "groups": [{"chapter": 0, "group": 0, "title": "Purpose and opening", "entries": [["Purpose", "Present what graduate assistants had reported; hear updates from Student Affairs and the Graduate School; identify issues still open; and agree on next steps together."], ["Opening practices", "Rishav read a land acknowledgement and asked participants to make space for one another’s viewpoints. The supplied accounts do not reproduce the acknowledgement or a complete code of conduct."], ["Introductions", "GAAC/GSA members introduced responsibility areas: health insurance and housing; pay and fees; contract renewals and speaking up; and the Meet & Confer process."]]}, {"chapter": 0, "group": 1, "title": "People and roles identified in the accounts", "entries": [["Student representatives", "S2 identifies Rishav as chair; Vaibhav as the CNMS representative presenting insurance and housing; Harshal as the COED representative presenting pay and fees; Enoch as the CAS representative presenting renewals and speaking up; and Daniel as the process presenter. These affiliations are reproduced as recorded, without independently verifying their abbreviations."], ["University participants", "S2 lists Dr. Kirsch (Student Affairs), Dr. Porter (Graduate School), Dr. Diaz (Dean of Students), Jennifer (GSA advisor), and the GAAC/GSA team. The president also spoke. This is an account of people identified in the synopses, not an independently checked attendance roll. Name and title inconsistencies are addressed in the source notes."]]}, {"chapter": 0, "group": 2, "title": "Survey figures reported in the meeting", "entries": [["Participation", "108 responses were discussed, from more than 500 GAs contacted or a GA population described as exceeding 500. The accounts describe representation across colleges and assistantship roles."], ["Insurance", "90% were reported to have flagged a health-insurance issue."], ["Pay and fees", "80% were reported to have flagged a pay, fee or stipend issue."], ["Contracts", "81% were reported to have flagged a contract-related issue."], ["Awareness", "55% reportedly did not know about GAC/GAAC."], ["Other concerns", "44% were reported to have raised immigration or transportation concerns. Rishav acknowledged that some of these concerns fall outside GAAC’s immediate scope but still matter to GAs."], ["Reading the figures", "These are percentages presented at the meeting, not a new analysis of the underlying survey. They describe different reported concerns and should not be added together or treated as mutually exclusive categories."]]}, {"chapter": 8, "group": 2, "title": "Praise for the approach and accountability", "entries": [["Constructive questions", "The president praised the group for raising real, difficult questions directly and for trusting leadership enough to bring them forward. The president suggested that other groups could learn from this model of conversation."], ["Shared purpose", "The remarks emphasized collaboration and service to students, questioned the need for conflict when the participants want the same broader outcome, and described the conversation as an example of how to work together."], ["Limits acknowledged", "Leadership cannot always say yes because money and other constraints remain. Praise for the meeting was not approval of every request."], ["Representative excerpt", "“This is how you do it.” [S1/S2]"], ["Another official’s response", "An official highlighted that students were asking questions, giving offices time to work and holding them accountable to return and report what had or had not been done."], ["Student communication", "Rishav said he intended to quote the president’s remarks at a student town hall so GAs could hear the university’s position. The problematic opening sentence should be checked against the recording before any quotation from it is circulated."]]}, {"chapter": 11, "group": 0, "title": "Why follow-through matters", "entries": [["Student confidence", "Rishav said some GAs felt they repeatedly raised issues without seeing them solved and worried they might give up. He thanked participants for listening and expressed hope that the responses and next steps would restore confidence."], ["Meaning of success", "The meeting enabled direct discussion, specific examples, leadership responses and several follow-ups. It also showed that remaining concerns could be raised openly. Success in holding the meeting should be distinguished from completion of the actions discussed."]]}, {"chapter": 11, "group": 1, "title": "What had already happened, according to the meeting", "entries": [["Completed changes or existing arrangements", "Early insurance enrollment, the corrected DocuSign sequence, a single insurance contact, the 1.5% minimum-stipend increase, widening of the Graduate Student Emergency Fund, and the emergency-housing partnership were reported as changes or arrangements already made. A broader all-student emergency fund was still being developed."]]}, {"chapter": 11, "group": 2, "title": "What was committed, planned or under consideration", "entries": [["Reporting and investigation", "Office reports, an affordability review and response, examination of semester-only notice, clearer grievance communication and case-specific follow-up were among the steps discussed."], ["Development work", "The appointment process, insurance/billing systems, stipend audit, pay bridge, broader emergency fund and additional ISSS staffing were at different stages of planning, review or implementation. Their exact status is preserved in the register below."]]}, {"chapter": 11, "group": 3, "title": "What remained unresolved", "entries": [["Material outcomes", "Reduced on-campus housing rates; a new adequate-living-cost stipend minimum; lower mandatory fees; universal GA insurance; an approved interest-free pay bridge; a notice rule for semester-only appointments; a new leave policy; and specific parking, workspace or urgent immigration remedies were not settled."], ["As-of date", "All action statuses in this report reflect what was said on November 18, 2026. Preparation on November 19 does not imply that any promised action has since been completed."]]}], "history": [["2023, reflecting on 2022", "GSA testimony argued that the existing process did not adequately capture or resolve concerns. This is a historical student account, not a claim about current legal requirements.", "testimony"], ["March 2026", "GAAC published a progress update connecting student concerns to workgroups and upcoming discussions.", "advocacy"]], "quote": ["UMBC president · supplied quotation-based account", "We are here to work in collaboration and in service to you."], "now": null}], "sources": {"record": {"title": "November 18, 2026 · Detailed meeting record", "url": "assets/meeting-record.pdf", "note": "Consolidated accounts, action register and complete source appendices. Working record, not approved minutes."}, "spring-gs": {"title": "Spring 2026 · Graduate School written report", "url": "assets/spring-2026-graduate-school.pdf", "note": "Earlier commitments; use the November record for the latest meeting status."}, "spring-ins": {"title": "Spring 2026 · Insurance written report", "url": "assets/spring-2026-insurance.pdf", "note": "Original process-improvement milestones."}, "fall-gs": {"title": "Fall 2026 · Graduate School pre-meeting update", "url": "assets/fall-2026-graduate-school.pdf", "note": "Written update supplied before the November 18 discussion."}, "agenda24": {"title": "December 3, 2024 · Meet & Confer agenda", "url": "assets/december-2024-agenda.docx", "note": "An agenda records issues and proposals, not proof of implementation."}, "spring-deck": {"title": "May 2026 · Meet & Confer presentation", "url": "assets/spring-2026-slides.pptx", "note": "Historical questions and concerns."}, "advocacy": {"title": "March 9, 2026 · GAAC advocacy update", "url": "https://my3.my.umbc.edu/groups/gaac/posts/157308"}, "testimony": {"title": "2023 · UMBC GSA legislative testimony", "url": "https://mgaleg.maryland.gov/cmte_testimony/2023/fin/14vkjWQ3X0gl4aQTvlgWqmhxmnyQX3gUw.pdf", "note": "Historical student testimony, including a retrospective account of fall 2022; not a current policy statement."}, "wisdom": {"title": "March 15, 2023 · GAAC insurance explainer", "url": "https://my3.my.umbc.edu/groups/gaac/posts/131800", "note": "Historical communication example; its plan-year benefits are not current guidance."}, "leadership": {"title": "UMBC · Senior leadership", "url": "https://umbc.edu/about/leadership/senior-leadership/"}, "provost": {"title": "UMBC · Provost leadership team", "url": "https://umbc.edu/about/leadership/provost/team/"}, "grad": {"title": "Graduate School · Staff and contact directory", "url": "https://gradschool.umbc.edu/staff/"}, "sa": {"title": "Student Affairs · Contact and office locations", "url": "https://studentaffairs.umbc.edu/about-us/contact/"}, "sa-units": {"title": "Student Affairs · Departments and services", "url": "https://studentaffairs.umbc.edu/about-us/work-with-us/"}, "global": {"title": "Center for Global Engagement · Teams", "url": "https://cge.umbc.edu/about/"}, "isss": {"title": "International students · Official contact and advising", "url": "https://isss.umbc.edu/contact/"}, "finance": {"title": "Administration and Finance · Departments", "url": "https://adminfinance.umbc.edu/"}, "equity": {"title": "Institutional Equity · Office responsibilities", "url": "https://my3.my.umbc.edu/groups/doie/posts/145671"}, "gaac": {"title": "GSA · GAAC and Meet & Confer", "url": "https://gsa.umbc.edu/gsa-committees/gaac/meet-confer/"}}, "timeline": [["Within about one week of Nov 18, 2026", "Send a summary of the Meet & Confer discussion", "Agreed reporting step; not described as already sent."], ["Dec 2, 2026", "Graduate program directors’ additional feedback on the GA template", "Feedback deadline given by Dr. Porter."], ["Dec 18, 2026", "Graduate School and Student Affairs written responses/reports", "Agreed target for the fall discussion."], ["January 2027", "Share results with GAs", "Planned communication/reporting; S2 describes a January town hall."], ["February 2027", "Aetna campus information session", "Being arranged; date not fixed."], ["Spring 2027", "Begin stipend review; give a clearer pay-bridge update; possible update on broader emergency support", "Planned work, not approved outcomes."], ["March 2027", "Further GA town-hall communication", "Mentioned in the discussion; no precise day established here."], ["April 15, 2027", "Next Meet & Confer; housing-affordability response", "Meeting date and housing follow-up discussed."], ["Late summer 2027", "Possible stipend-audit report/share-out", "Dr. Porter’s expectation; no immediate budget change promised."], ["Summer / fall 2027", "Soft-launch the revised appointment process for new GAs", "Goal, subject to consultation and implementation work."]], "actions": [["A01", "Post-meeting summary", "Rishav / GAAC", "Within about one week of Nov 18", "Agreed reporting step", "Describe the discussion and outcomes; not recorded as already sent. [S1 §7/9; S2 Actions; S3 §6]"], ["A02", "Written office responses", "Graduate School and Student Affairs", "Dec 18, 2026", "Agreed target", "Provide written reports for the fall discussion. [S1 §7/9; S2 Actions; S3 Closing]"], ["A03", "Prepare the January report and share results with GAs", "Rishav / GAAC", "January 2027; further March communication", "Planned reporting", "Prepare the January town-hall report using the offices’ December 18 written responses, then share results. March town-hall communication is also mentioned. The preparation step is explicit in the latest S2 checklist. [S1 §6/9; S2; S3 Closing]"], ["A04", "Include GAAC in insurance-plan review", "Student Affairs / insurance process participants", "Late December or early spring, tentative", "Participation supported", "Invite/update GAAC when the top-plan discussions are scheduled; no changed benefit promised. [S1 §2; S3 §1]"], ["A05", "Investigate dental/vision discrepancies", "GAAC to provide cases; Student Affairs to investigate", "No date recorded", "Specific cases requested", "Collect affected students’ names and send them to Jennifer, as the latest S2 checklist specifies; investigate missing dental/vision displays and inconsistent access. [S1 §2; S2 Actions; S3 §1]"], ["A06", "Improve Aetna answers and guidance", "Student Affairs / insurance committee; Aetna feedback", "No date recorded", "Work discussed / in progress", "Clarify cards, benefits, web/app differences and educational resources; convey incorrect telephone-answer feedback. [S1 §2; S3 §1]"], ["A07", "Aetna campus session", "Student Affairs / Aetna", "February 2027, date pending", "Being arranged", "Student information and question session; not completed. [S1 §2; S2; S3 §1]"], ["A08", "Insurance and billing system assessment", "Student Affairs", "No selection date recorded", "Evaluation in progress", "Two demos reviewed; consider proposals and financial-cycle fit. No system selected. [S1 §2; S3 §1]"], ["A09", "Clarify coverage between appointments", "Student Affairs; departments for forms", "No written-guidance deadline recorded", "Guidance requested; process explained", "Explain December-January situations and ensure new forms are filed; individual cases not all resolved. [S1 §2; S2; S3 §1]"], ["A10", "Unified appointment/insurance/tuition paperwork", "Graduate School and relevant offices with DoIT", "Development ongoing", "In development", "Combine forms; interim departmental reminders were discussed. [S1 §2/5; S2; S3 §1/4]"], ["A11", "Review on-campus GA housing affordability", "Student Affairs leader; S2 names Dr. Kirsch", "Response April 15, 2027", "Explicit review/report commitment", "Report what was explored and possible options; detail and reduced rates not guaranteed. [S1 §3; S2 Actions; S3 §2]"], ["A12", "Share housing-demand insights", "Student Affairs / housing-study participants", "April if insights are available", "Conditional offer", "Study may not be complete; includes graduate focus groups, local costs and potential housing/partnership options. [S1 §3; S3 §2]"], ["A13", "Participate in future fee consultations", "Graduate School", "Future fee conversations", "Participation commitment", "Be at the table; no existing fee reduction was agreed. [S1 §4; S2; S3 §3]"], ["A14", "Graduate emergency-fund support", "Graduate School", "No further date recorded", "Widening reported; further support intended", "Exact amounts and revised application rules not stated. [S1 §4; S2; S3 §3]"], ["A15", "All-student emergency fund", "Dean of Students Office", "Possible spring 2027 update", "In development", "Donation-supported fund; distinct from Graduate Student Emergency Fund. [S1 §4; S2; S3 §3]"], ["A16", "Emergency housing", "Relevant student-support offices / Maritime Conference Center", "Partnership established; access timing not specified", "Partnership reported", "Emergency housing and dining support would be made available; current access and operating details were not confirmed. [S1 §4; S2; S3 §3]"], ["A17", "Internal stipend audit", "Graduate School / Dr. Porter", "Start spring; share-out expected late summer 2027", "Planned review", "Review across departments, acknowledge differing student costs; no immediate increase promised. [S1 §4; S2 Actions; S3 §3]"], ["A18", "Pay-bridge feasibility and benchmarking", "Graduate School with General Counsel and Financial Aid; Cheryl named in S1", "Clearer update expected spring 2027", "Under review", "Assess legal, tax and international-student implications and peer approaches. [S1 §4; S2; S3 §3]"], ["A19", "Check peer loan interest rates", "Dr. Porter / benchmarking process", "No separate date recorded", "Agreed to check", "Whether peer loans are interest-free or lower-interest remained unanswered. [S1 §4; S3 §3]"], ["A20", "Collect appointment-template feedback", "Graduate program directors; Graduate School", "Dec 2, 2026", "Stated feedback deadline", "Additional feedback, followed by process/DoIT work. [S1 §5; S3 §4]"], ["A21", "Launch revised appointment process", "Graduate School, DoIT and academic units", "Summer / fall 2027 goal", "Tentative rollout", "New GAs first; earlier spring aim delayed for consultation and implementation. [S1 §5; S3 §4]"], ["A22", "Renewal reminders and missed-notice intervention", "Graduate School / Dr. Porter; GAs report problems", "Applicable notice cycles; no case-response deadline", "Stated practice / intervention", "Remind departments and contact those missing requirements; funding discontinuation cited as a possible valid exception. [S1 §5; S2; S3 §4]"], ["A23", "Examine semester-only notice gap", "Dr. Porter / Graduate School", "No deadline recorded", "Commitment to investigate", "Review the longer-than-one-semester clause and what notice UMBC should establish. [S1 §5; S2 Actions; S3 §4]"], ["A24", "Handle supervisor/funding concerns", "Graduate School; associate dean identified in sources", "As concerns arise", "Referral and protection described", "Contact Graduate School; mediation or committee as appropriate; continued duties/pay and no removal during process were described. [S1 §6; S2; S3 §5]"], ["A25", "Clarify grievance route", "Graduate School; Student Affairs for links; GAAC for communication", "Handbook revision ongoing; no publication date", "Clarity discussed; format not final", "Handbook/web guidance and a possible chart; S2 states the chart more definitively than S3. [S1 §6; S2; S3 §5]"], ["A26", "Explain decisions and consult early", "Graduate School and Student Affairs with GAAC", "Future decisions and written updates", "Supported reporting practice", "Use the workgroup model; explain reasoning and GA input. No formal new governance mechanism specified. [S1 §7; S2; S3 §6]"], ["A27", "Clarify leave and bereavement", "Graduate School with General Counsel; GAAC supplies examples", "No deadline recorded", "Further work discussed", "Gather departmental examples and consider handbook clarity; no entitlement adopted. [S1 §8; S2 Actions; S3 §7]"], ["A28", "Faculty-space follow-up and GA space concerns", "Responding leader / deans / departments; S2 names Dr. Kirsch", "No deadline recorded", "Follow-up stated; broader review underway", "Check the unverified faculty-space example; identify specific GA pain points; no allocation promised. [S1 §8; S2; S3 §7]"], ["A29", "Schedule a focused parking/transport meeting", "Saad or Student Affairs; Daniel Teach and Gina suggested", "No meeting date recorded", "Recommended at meeting; scheduling listed in latest S2", "The latest S2 checklist calls for scheduling via Saad or Dr. Kirsch with Daniel Teach. Gina could join. Discuss parking and service changes; an advisory board was mentioned. [S1 §8; S2 Actions; S3 §7]"], ["A30", "Improve ISSS capacity", "ISSS / relevant university staffing process", "Hiring during the fall semester", "Staffing update", "Additional staff expected to help; no urgent-case service target adopted. [S1 §8; S2; S3 §7]"], ["A31", "Post-meeting newsletter", "GAAC, with Student Affairs suggestion/support", "After Meet & Confer; no fixed date", "Suggestion", "Summarize outcomes and routes for help; distinguish from the agreed one-week summary. [S1 §6; S2 Ad-Hoc; S3 §5]"], ["A32", "Calendar and agenda for the next Meet & Confer", "GAAC and university participants", "April 15, 2027", "Date discussed; preparation added in latest S2", "The latest S2 checklist says to add April 15 to the calendar and prepare the agenda. An invitation was already reported shared at the meeting; no spring written-response date was specified. [S1 §7/9; S2; S3 §6/Closing]"], ["A33", "Follow up on spring pay-bridge and stipend-audit timelines", "GAAC / Rishav, following up with the Graduate School", "Spring 2027", "Latest S2 checklist task", "The latest Detailed Talk explicitly asks for this follow-up. It is a GAAC planning task in addition to the Graduate School work recorded in A17-A19, not evidence that a program or pay increase was approved. [S2 Final Action Items]"]], "chapters": [{"title": "Opening, participants and survey context", "intro": "The Fall 2026 GAAC Meet & Confer took place on November 18, 2026. Rishav opened it as the first meeting under the USM Board of Regents policy requiring two meetings each year. That description records how the meeting was introduced; this report does not independently interpret the policy. [S1 §1; S2 Opening; S3 Opening]", "groups": [["Purpose and opening", [["Purpose", "Present what graduate assistants had reported; hear updates from Student Affairs and the Graduate School; identify issues still open; and agree on next steps together."], ["Opening practices", "Rishav read a land acknowledgement and asked participants to make space for one another’s viewpoints. The supplied accounts do not reproduce the acknowledgement or a complete code of conduct."], ["Introductions", "GAAC/GSA members introduced responsibility areas: health insurance and housing; pay and fees; contract renewals and speaking up; and the Meet & Confer process."]]], ["People and roles identified in the accounts", [["Student representatives", "S2 identifies Rishav as chair; Vaibhav as the CNMS representative presenting insurance and housing; Harshal as the COED representative presenting pay and fees; Enoch as the CAS representative presenting renewals and speaking up; and Daniel as the process presenter. These affiliations are reproduced as recorded, without independently verifying their abbreviations."], ["University participants", "S2 lists Dr. Kirsch (Student Affairs), Dr. Porter (Graduate School), Dr. Diaz (Dean of Students), Jennifer (GSA advisor), and the GAAC/GSA team. The president also spoke. This is an account of people identified in the synopses, not an independently checked attendance roll. Name and title inconsistencies are addressed in the source notes."]]], ["Survey figures reported in the meeting", [["Participation", "108 responses were discussed, from more than 500 GAs contacted or a GA population described as exceeding 500. The accounts describe representation across colleges and assistantship roles."], ["Insurance", "90% were reported to have flagged a health-insurance issue."], ["Pay and fees", "80% were reported to have flagged a pay, fee or stipend issue."], ["Contracts", "81% were reported to have flagged a contract-related issue."], ["Awareness", "55% reportedly did not know about GAC/GAAC."], ["Other concerns", "44% were reported to have raised immigration or transportation concerns. Rishav acknowledged that some of these concerns fall outside GAAC’s immediate scope but still matter to GAs."], ["Reading the figures", "These are percentages presented at the meeting, not a new analysis of the underlying survey. They describe different reported concerns and should not be added together or treated as mutually exclusive categories."]]]]}, {"title": "Health insurance: enrollment, benefits and access", "intro": "Vaibhav introduced the insurance discussion according to S2. Representatives acknowledged completed enrollment improvements, then tested the offices’ description of coverage against specific student experiences. [S1 §2; S2 Health Insurance; S3 §1]", "groups": [["Improvements acknowledged for fall 2026", [["Early enrollment", "More than 500 GAs were enrolled before the semester began. The accounts describe enrollment before August 14, ahead of an approximately August 30 semester start, with the aim of avoiding access gaps."], ["DocuSign order", "The signing order was corrected so that departmental approval was no longer a prerequisite for insurance enrollment."], ["One contact", "Jennifer was established as the single point of contact for insurance concerns, reducing uncertainty about whom a student should approach."]]], ["Question 1: Can GAAC review the next plan before it is selected?", [["Question and follow-up", "Could GAAC review both coverage and cost before the next insurance plan is chosen? How would dental, vision, dependent and mental-health concerns be considered in that decision?"], ["Response", "The office supported GAAC participation. It described the earlier practice of inviting students when the top two or three prospective plans came to campus to explain their offerings, and proposed using that approach again."], ["Timing", "Late December or early spring was mentioned tentatively. GAAC would be updated once the discussion was scheduled. No selection date, new benefit or change in coverage was promised."]]], ["Benefits as described by the office", [["Mental health", "The response described care through Retriever Integrated Health as free and outside care as involving a copay. This records the explanation given, not a verification of every service, provider or student’s eligibility."], ["Dental and vision", "The office said both were included, while acknowledging that vision information was unclear on the website. Student accounts below showed that visibility, interpretation and access remained unresolved."], ["Dependents", "Whether dependent coverage is paid for was described as department-dependent. The discussion did not establish a universal employer-paid dependent benefit."]]], ["Student instances: retain each separately", [["Dental missing for full-time GAs", "Rishav reported that some full-time GAs saw dental in their Aetna portal while others did not. The office asked for affected students’ names or identifiable cases so staff could investigate and correct the records. The latest Detailed Talk checklist specifically says to collect those names and send them to Jennifer."], ["Vision missing and an incorrect telephone answer", "One attendee saw medical and dental but no vision in the portal. They called Aetna and were told they did not have vision, spent roughly three years believing that, and then discovered at an eye-care visit in the past year that a copay/vision benefit applied."], ["Exam discount and expensive lenses", "Another attendee described an eye exam priced at $75, reduced to $49 through Aetna, with more involved lenses costing over $150. They understood this as a discount rather than the expected coverage and questioned what the benefit actually provided."], ["Provider acceptance", "The same discussion included a report that a provider did not accept the student plan. This is a distinct access problem from whether a benefit is listed in the portal."], ["App versus browser", "An attendee’s app showed only dental, while the browser showed both cards. The accounts therefore identified inconsistent displays across access methods as well as confusion over the benefits themselves."]]], ["Responses, planned guidance and system assessment", [["Correct answers from Aetna", "The responding office acknowledged the need for Aetna to provide accurate answers when students call and said this feedback should be taken back to the insurer."], ["Website and educational materials", "Work with the insurance committee included clearer website information about coverage, where to find cards, presentations, and how-to guidance. Existing videos and glossaries, including resources useful to international students, were discussed. S2 describes how-to videos as planned; S1 also describes links to existing materials."], ["February information session", "An Aetna campus session for students to ask questions was being arranged for February. The date was still being worked out; the meeting did not establish that it had already occurred or that a final date was booked."], ["Two system demonstrations", "Student Affairs was assessing the insurance and billing process as a whole. It had recently seen two demonstrations, described in S3 as the previous week. One system was built for student health centers and might clarify timelines, charges and coverage internally, alongside Aetna’s own site."], ["Procurement status", "The next steps were to consider proposals and fit with the financial cycle. No system had been selected, funded or launched in the discussion."], ["What remained open", "Individual dental and vision discrepancies, provider acceptance, dependable instructions and the timing of student participation in plan review still required follow-through. The meeting did not establish that all students could see or use every benefit as described."]]]]}, {"title": "Insurance between appointments and combined paperwork", "intro": "The discussion separated the stated annual plan period from the administrative difficulty students experience when appointment or insurance paperwork is late. [S1 §2; S2 Health Insurance; S3 §1]", "groups": [["Question 2: What coverage applies during breaks and between contracts?", [["Main question", "Could Student Affairs provide clear written rules for breaks and the period between contracts? If an appointment ends before the next begins, what options would UMBC offer so the student is not uninsured?"], ["Dates given", "The plan period was described as August 15, 2026 through August 14, 2027. The enrollment window was stated as August 4 through September 15."], ["Administrative explanation", "The response said that a student’s apparent lack of immediate coverage often resulted from a department not yet submitting insurance paperwork. It distinguished such processing problems from an actual lapse, while acknowledging that students may not know where they stand."]]], ["Question 3: What about an appointment ending in December and restarting in January?", [["Specific instance", "Rishav raised semester-based contracts that end in early December, with the next spring offer beginning in January. He described students’ concern that the intervening period is not covered."], ["Response", "The response was that students with a new contract starting should still be covered, but departments must complete a new form. S2 attributes this explanation to Dr. Porter; the quotation-based account labels the speaker only as a respondent."], ["Important limit", "This was an explanation of how the process should operate. The discussion did not resolve every individual case, establish what happens without a succeeding appointment, or document a newly issued written rule."]]], ["Preventing missed forms", [["Current weakness", "Appointment letters, insurance forms and tuition-remission paperwork were handled separately. A speaker said separate forms are easy for departments to overlook."], ["Unified process", "Participants described work with DoIT on a combined appointment-letter, insurance and tuition-remission process so the required elements can be handled together."], ["Interim reminders", "Renewal and submission reminders were proposed as a practical way to help departments while the combined process is still being developed."], ["Follow-through required", "The requested written guidance and case-specific resolution were not presented as completed. The combined process was still in development, not an operational fix that all students could already use."]]]]}, {"title": "On-campus housing affordability", "intro": "The housing discussion produced a commitment to investigate affordability and report back, while leaving reduced rates undecided. [S1 §3; S2 Health Insurance; S3 §2]", "groups": [["Question 4: Are on-campus rates affordable, and can UMBC explore a reduced GA rate?", [["Question and ownership", "The representative asked UMBC to assess whether on-campus housing is affordable on a GA stipend, explore a reduced rate, identify who would lead the review and specify when GAAC would receive a response."], ["Survey evidence presented", "50% of the 108 respondents were described as identifying housing as their biggest financial burden."], ["Cost illustration", "The example was approximately $1,200 per month for an on-campus bedroom or bed, compared with a $1,800-$2,000 monthly stipend. Speakers described rent as roughly 70% of that stipend. S2 calls the unit a one-bedroom; the other accounts say a bedroom or one bed. The report preserves the illustration without treating the unit description as settled."], ["Numerical qualification", "At the exact figures quoted, $1,200 is 60%-66.7% of $1,800-$2,000. The “roughly 70%” figure is retained as the meeting’s characterization rather than silently substituted as a calculated result."]]], ["Leadership response and commitment", [["Review versus reduction", "Housing fees are reviewed annually and apply across students. A special reduced rate would need a more detailed conversation beyond simply reviewing whether existing costs are affordable."], ["Affordability acknowledged", "The responding leader suggested that rates might well be unaffordable for GAs, but said the issue should be tested against data."], ["Lead and report back", "S2 identifies the Student Affairs leader as Dr. Kirsch and records a commitment to lead the affordability conversation. The leader agreed to return at the April 15 Meet & Confer with a response on what had been explored and possible options."], ["Limit of the commitment", "The leader could not promise the level of detail available by then. A reduced GA rate was not approved, and no implementation date or funding source was agreed."]]], ["Housing-demand study", [["Scope", "An ongoing study includes student focus groups, including graduate students; on-campus costs; nearby apartment-community costs; housing demand; and what students could afford if UMBC built additional housing or pursued local partnerships."], ["Timing", "The study might not be finished by April. The response offered to share any available insights at that time, rather than promising a completed study by the next meeting."], ["Open questions", "Affordability findings, possible reduced rates, other housing options and the practical response to the study remained outstanding."]]]]}, {"title": "Pay, fees, workload and emergency support", "intro": "Harshal presented pay and fee concerns according to S2. Representatives connected the formal stipend minimum to the money students actually have left after required costs. [S1 §4; S2 Pay and Fees; S3 §3]", "groups": [["Concerns and concrete comparisons", [["Mandatory fees", "Approximately 74% of respondents were said to consider mandatory fees too high and rising each year. The quotation-based account preserves the speaker saying “75% or 74%.” Representatives described GAs as living paycheck to paycheck."], ["Unequal insurance support", "Some half-GAs and students dividing their work between part-time RA and TA appointments reportedly did not receive the same benefit as other GAs. A figure of about 40% paying premiums out of pocket was presented; the supplied accounts do not establish that figure’s exact denominator."], ["Late first paycheck", "Some GAs did not receive their first paycheck on time that semester. The record does not establish how many, identify individual cases or document a guaranteed payroll remedy."], ["Workload differences", "Representatives contrasted remote TA work with roles requiring campus attendance, including an example of two classes per week rather than one. They questioned whether differences in duties and workload were reflected in stipends or support. No new workload standard or adjustment was agreed."]]], ["Cost-of-living increase and participation in fee decisions", [["1.5% increase", "Dr. Porter said the Graduate School had advocated for and secured a 1.5% cost-of-living increase. The updated minimum was published on the website in July. She acknowledged the modest size of the increase."], ["Fees outpacing support", "Rishav questioned whether the 1.5% adjustment kept pace with rising mandatory fees and housing costs. The broader concern was whether a GA could live adequately on the remaining income."], ["Graduate School at the table", "Dr. Porter said the Graduate School had not previously participated in fee conversations but would now be involved in future consultations. The exchange did not explain, reverse or reduce the existing fees."]]], ["Three different emergency-support mechanisms", [["Graduate Student Emergency Fund", "Dr. Porter said the fund had been widened somewhat, acknowledged that the money was limited and expressed an intention to increase support. The accounts do not specify the amount, award size, revised eligibility, application route or guaranteed assistance for a particular student."], ["Dean of Students emergency fund", "A separate fund for all students was being developed through the Dean of Students Office following generous donations. Staff were still working through the process and hoped to share more in spring. It should not be merged with the graduate-specific fund in reporting."], ["Emergency housing", "A partnership with the Maritime Conference Center, described as a full facility with dining, had been established. The response said support would be made available for true emergency housing needs; operating details and current access were not confirmed."], ["Limits", "These supports were discussed as emergency assistance. They did not settle the underlying stipend, fee, ongoing housing-affordability or universal insurance questions."]]]]}, {"title": "Stipend review, minimum insurance and the proposed pay bridge", "intro": "Three separate requests concerned the adequacy of regular compensation, a minimum benefit for every GA and short-term help during a funding interruption. [S1 §4; S2 Pay and Fees; S3 §3]", "groups": [["Question 5: Will the stipend review account for actual living costs?", [["Question", "Representatives asked whether the review would consider housing, mandatory fees and insurance premiums, rather than only whether each department meets the formal stipend minimum."], ["Audit scope and start", "Dr. Porter described an internal review of UMBC graduate stipends across departments beginning in spring."], ["Expected reporting", "A report or share-out was unlikely before late summer. This was an expectation rather than an adopted delivery deadline."], ["Budget authority", "Departments and colleges control their budgets, which may already be set by the time findings are available. A review would therefore not necessarily produce an immediate pay increase."], ["Existing minimum", "Dr. Porter said departments must meet the current minimum and would have to meet a new minimum if it is increased."], ["Different net resources", "She acknowledged that the same nominal stipend leaves students in different positions when some must pay their own insurance. She supported continuing an honest conversation and putting the numbers before academic colleagues."], ["Not settled", "No new stipend minimum, specific cost-of-living formula, automatic adjustment mechanism or increase date was promised."]]], ["Question 6: Could every GA receive a minimum insurance benefit?", [["Question", "Could UMBC establish a minimum insurance benefit across GA appointments rather than leaving support to the department? The examples included half appointments and split RA/TA work."], ["Response", "Dr. Porter said she had advocated for the goal, but described insurance, stipend and tuition as a nuanced budget question."], ["Trade-off stated", "If departmental funding remains flat, requiring a more expensive package for every GA could reduce the number of GA positions."], ["Not settled", "Agreement with the aim did not amount to approval of universal coverage or a commitment to additional departmental funding."]]], ["Question 7: Could a pay bridge provide an interest-free loan during gaps?", [["Question", "Representatives asked about an interest-free loan or similar bridge when pay or funding stops between appointments, or when funding is cut between semesters."], ["Legal and financial review", "Dr. Porter said the Graduate School was consulting General Counsel and Financial Aid about implications, including tax consequences and differences affecting international and domestic students. The stated goal was to avoid creating harm for recipients."], ["Benchmarking", "Other institutions’ approaches were being examined. S1 identifies Cheryl as doing that benchmarking; the role and spelling are not independently verified here."], ["Expected update", "Dr. Porter expected a clearer sense in spring. The idea was still under review; no loan program had been approved or launched."]]], ["Question 8: Are peer institutions’ loans interest-free or lower-interest?", [["Follow-up", "A representative specifically asked whether the institutions being benchmarked offered zero interest or simply a lower rate."], ["Answer", "Dr. Porter said she did not yet know and would check."], ["Open terms", "The meeting did not establish an interest rate, fees, eligibility, amount, repayment schedule or approval process. The synopsis phrase “interest-free loan” describes the request, not an approved feature."]]]]}, {"title": "Appointment documents and renewal notice", "intro": "The Graduate School described a developing appointment process and responded to two distinct notice questions: enforcement where 60 days applies, and the position of semester-only GAs. [S1 §5; S2 Contract Renewals; S3 §4]", "groups": [["Revised appointment template", [["Consultation", "Dr. Porter reported consultation with graduate program directors, some department chairs and students, and planned contact with deans. She thanked students for their involvement."], ["What the document would contain", "The template would set out expectations, communication strategies and arrangements, stipend and benefits, and additional departmental or supervisory requirements. S1 also records signatures from the GA and supervisor."], ["Feedback deadline", "Graduate program directors had until December 2 to submit additional comments. DoIT work on the process would follow."], ["Schedule change", "An earlier spring launch goal had shifted to a summer soft launch, with the discussion pointing toward fall 2027 use. Dr. Porter explained that due diligence, consultation and implementation were taking longer than hoped."], ["Initial coverage", "The initial rollout would apply to new GAs. Requiring departments and chairs to redo documentation for all existing GAs at once - described in the discussion as about 600 students - would be a substantial workload."], ["Status", "The desired outcome was a clearer, unified electronic appointment process. It was not described as already operational for all GAs."]]], ["Question 9: What justifies less than 60 days’ notice, and what happens if a department misses it?", [["Question", "Where the 60-day guidance applies, what counts as a valid reason for shorter notice? What would the Graduate School do if a department misses the deadline without a valid reason?"], ["Possible exception", "Dr. Porter gave discontinued funding, such as a grant ending or no longer being available, as an example of a valid reason. She emphasized that there were not many valid reasons for missing notice."], ["Intervention", "She said she would contact the department or the person missing the deadline. No automatic penalty, guaranteed renewal or compensation for missed notice was specified."], ["Reminders and example", "The Graduate School would send reminders. An August 15 appointment start was used to illustrate a reminder date around June 16."], ["Question 10: Should the student report missing notice?", "When a representative asked whether students should contact the Graduate School if they do not receive follow-up, Dr. Porter answered yes, emphatically. Students were not told to assume the Graduate School already knows."]]], ["Question 11: What notice should a semester-only GA receive?", [["Question", "How far in advance should someone hired for one semester learn whether they will be renewed? Could UMBC set a clear minimum so students can plan finances and housing?"], ["Initial response", "Dr. Porter said the 60-day rule comes from USM, not a UMBC-created rule, and initially said she did not think it distinguished semester appointments from nine- or twelve-month appointments."], ["Clarification in the room", "A representative pointed to language applying the 60 days to contracts longer than a semester. Dr. Porter acknowledged the clause and said she would examine the issue further and what needed to be established."], ["Unresolved outcome", "No minimum notice period for semester-only GAs was settled. This report records that unresolved exchange rather than converting the initial response into a definitive policy interpretation."]]]]}, {"title": "Speaking up, funding loss, mediation and retaliation", "intro": "Enoch presented the contract and speaking-up questions according to S2. The exchange addressed both the route for raising concerns and whether a student remains supported during review. [S1 §6; S2 Contract Renewals; S3 §5]", "groups": [["Question 12: Who outside the department reviews funding loss after a complaint?", [["Question", "If a GA raises a concern about a supervisor and then loses funding, how would someone outside the department determine whether the events are connected? What support would the GA receive during that review?"], ["Immediate route", "Dr. Porter instructed students to contact the Graduate School about a funding loss or supervisor concern."], ["Contact identified", "The supplied accounts name Associate Dean “Rodney Couvert” as the person receiving such concerns. That is transcript-derived wording; the official spelling and contact details should be checked before the name is used as a referral."], ["Review process", "The Graduate School could use its mediation process or decide whether a separate committee was appropriate. The meeting did not establish an automatic outside committee, a finding of retaliation in a particular case, or a standard remedy for all funding losses."]]], ["Question 13: What protects the student’s income and appointment during the process?", [["Rishav’s concern", "The handbook mentions retaliation but does not show a clear pathway: where to go, what happens after a report and how a review works. Students need to understand the route before they can confidently use it."], ["Concrete support request", "Rishav asked whether a student whose RA appointment is cancelled could receive a TA appointment or a pay bridge so the student does not suddenly lose all financial support. No automatic substitute TA appointment or bridge entitlement was approved."], ["Protection described by Dr. Porter", "Departments had been told not to move forward with removal while the Graduate School process is playing out. She said the student should continue being paid, performing duties and remaining in the appointment during that process."], ["Limits of this record", "The statements were assurances made at the meeting. The accounts do not supply a complete written procedure covering every funding source, case type, duration, appeal or emergency intervention."]]], ["International students’ fears: concerns reported, not adjudicated cases", [["Fear of speaking", "A representative said international students were scared to raise concerns and had been advised by others to keep quiet because nothing would happen."], ["Fear of losing opportunities", "Students worried that a complaint could damage the advisor relationship, cause a grant or funding to be cancelled, or lead other departments to blacklist them or withhold another appointment."], ["Status of the examples", "These statements describe fears and reported experiences voiced in the discussion. The meeting did not establish findings against a named department or supervisor."]]], ["Clearer guidance and routes", [["Handbook revision", "Dr. Porter said the GA handbook was being revised. A grievance chart, clearer website guidance and more explicit handbook language were discussed as ways to make the process understandable."], ["Certainty of the chart", "S2 says a chart and clearer pathway will be added; S1 and S3 frame a chart as one possible way to improve clarity. The reliable common point is that revision and clearer communication were discussed, while the final format was not established in the quotation-based account."], ["Student Affairs communication", "Student Affairs offered to link to Graduate School resources and tell students where to go through its own website. A newsletter after Meet & Confer was suggested, including the most useful outcomes and contact routes."], ["College-level options", "Dr. Porter encouraged students to approach a dean, associate dean, assistant dean or department chair when appropriate."], ["Direct Graduate School access", "She explicitly recognized that an advisor, supervisor or graduate program director may be involved in the concern. Where trust or comfort is lacking, students should come directly to the Graduate School; college-level contact was not presented as an absolute prerequisite."], ["Sharing the information", "The accounts discuss communicating outcomes in January and through a March town hall so students know what changed and how to seek help."]]]]}, {"title": "The president’s remarks and feedback on the meeting", "intro": "The accounts record a strong rejection of retaliation and praise for GAAC’s constructive approach. Quotations below are excerpts from the supplied synopsis, not independently checked audio. The full passages and their qualifications are retained in the source appendices. [S1 §6; S2 Contract Renewals and Ad-Hoc; S3 §5]", "groups": [["Institutional assurance on retaliation", [["Position", "The president said retaliation is unacceptable and that the university has a responsibility to protect students when raising an inappropriate experience leads to retaliation."], ["International students", "The remarks explicitly addressed students regardless of where they come from. They rejected the idea that the surrounding political or federal context removes students’ human rights or the university’s responsibility to respond."], ["Leadership involvement", "The accounts describe the Graduate School, provost and president acting when concerns reach them. The president acknowledged that it is easier for leadership to say “don’t be afraid” than it is to be the student facing the risk."], ["Representative excerpt", "“Be confident that your university Has your back on that, right? It really does.” [S3]"], ["Meaning and limit", "These were institutional assurances, not a complete operational grievance policy or a promise that a particular remedy would apply in every case. The need for clearer reporting and review instructions remained."]]], ["Transcript problem that must stay visible", [["Conflicting opening sentence", "S1 reproduces a visibly corrupted opening that appears to call retaliation acceptable, then immediately explains that the next statements reject it. S2 renders that opening with “not acceptable.” S3 avoids quoting the corrupted sentence and provides the surrounding clear statements."], ["Editorial treatment", "This report does not turn either version into a verified standalone quotation. The clear rejection is summarized above; all supplied wording remains available in the documentary appendices with this warning."]]], ["Praise for the approach and accountability", [["Constructive questions", "The president praised the group for raising real, difficult questions directly and for trusting leadership enough to bring them forward. The president suggested that other groups could learn from this model of conversation."], ["Shared purpose", "The remarks emphasized collaboration and service to students, questioned the need for conflict when the participants want the same broader outcome, and described the conversation as an example of how to work together."], ["Limits acknowledged", "Leadership cannot always say yes because money and other constraints remain. Praise for the meeting was not approval of every request."], ["Representative excerpt", "“This is how you do it.” [S1/S2]"], ["Another official’s response", "An official highlighted that students were asking questions, giving offices time to work and holding them accountable to return and report what had or had not been done."], ["Student communication", "Rishav said he intended to quote the president’s remarks at a student town hall so GAs could hear the university’s position. The problematic opening sentence should be checked against the recording before any quotation from it is circulated."]]]]}, {"title": "Participation, decision explanations and reporting", "intro": "Daniel referred to the mandated November 12 dialogue training involving GAAC and GSA members, then asked how student input and follow-through should work. [S1 §7; S2 Meet and Confer Process; S3 §6]", "groups": [["Question 14: How can GAAC be involved before decisions are effectively made?", [["Question", "How can GAAC participate early in decisions affecting appointments and pay, alongside the administration?"], ["Response", "The appointment-template workgroup was cited as an example of involving GAAC while a proposal is being developed. Officials said that model could be used in future decisions and emphasized the importance of having students at the table."], ["Limit", "No new standing committee, consultation deadline or formal decision right was established in the supplied accounts."]]], ["Question 15: Will written updates explain the reasoning and how GA input was used?", [["Question", "Could future written updates explain how GA input was considered or implemented and why a decision was made? Daniel emphasized that students want to understand the process, not just see an outcome."], ["Response across sources", "S1 and S2 describe agreement to improve explanation, with S2 attributing it to Dr. Porter and Dr. Kirsch. S3 preserves only a brief affirmative response, “Okay, great.” The report records the requested reporting practice and the summarized agreement without inventing a detailed explanation that was not supplied."]]], ["Question 16: Who will maintain a shared record, and when will people hear back?", [["Question", "Daniel asked about a shared action record identifying the obligations accepted by different offices and when GAAC and the wider GA community would receive updates."], ["Agreed sequence", "Rishav proposed a summary within about one week of November 18, written Graduate School and Student Affairs responses by December 18, and sharing results with GAs in January. The exchange recorded assent."], ["Who does what", "The supplied action list assigns the post-meeting summary and student communication to Rishav/GAAC and written office reports to the Graduate School and Student Affairs. The latest Detailed Talk checklist explicitly adds preparing the January town-hall report using the December 18 office responses, following up on spring pay-bridge and stipend-audit timelines, and preparing the April 15 agenda. It does not designate a separate administrator for a shared tracking system."], ["Next meeting", "Rishav confirmed April 15 as the next Meet & Confer and said the calendar invitation had already been shared."], ["Spring reporting", "Participants asked about spring and discussed a similar reporting interval after the spring meeting. No spring written-report date was specified; this document does not invent one."], ["Communication formats", "S2 calls January sharing a town hall; S1 and S3 describe January reporting and subsequent town-hall communication, with March also mentioned. Both references are preserved as recorded rather than assuming a single confirmed town-hall date."]]]]}, {"title": "Additional concerns: leave, space, parking and immigration", "intro": "Rishav placed four further topics on the record near the end and asked who could help address them. These received shorter responses than the earlier agenda items. [S1 §8; S2 Additional Issues and Action Items; S3 §7]", "groups": [["Question 17: Can leave and bereavement rules be clarified?", [["Problem", "Rishav said GAs on a one-year contract lacked a clear leave and bereavement policy. The response acknowledged that the handbook is unclear; it did not establish that no relevant protection of any kind exists."], ["Response", "The Graduate School would consider clearer guidance and work with General Counsel. S2 describes this as a commitment; the quotation-based account phrases it as work to consider."], ["Request to GAAC", "Officials asked for concrete examples of how requests arise and how different departments handle them so the problem can be understood in practice."], ["Open outcome", "No new leave entitlement, number of days, bereavement allowance, approval process or interim rule was agreed."]]], ["Question 18: Who can address office and lab-space shortages?", [["Student experience", "Rishav described crowded shared computer-science labs and multiple faculty/lab groups sharing space in the college rendered as “COIT” in S3."], ["Specific, unverified instance", "He relayed that a newly hired CS professor reportedly lacked an assigned lab and explicitly said, “don’t quote me on this.” The response referred to an office. The account does not establish the faculty member’s actual assignment or whether the issue concerns a lab, office or both."], ["Response and follow-up", "A leader said the reported absence of faculty space was concerning and that they would follow up. S2 attributes that response to Dr. Kirsch; S1/S3 do not reliably identify the speaker."], ["Broader review", "The university was stepping back with deans to assess space utilization, particularly while hiring faculty. Students were encouraged to identify exact pain points to departments and colleges."], ["Sherman 2", "S1 says Sherman 2 was “coming along”; S2 calls construction on schedule. Neither establishes an immediate workspace solution for a particular GA."], ["Open outcome", "No GA workspace allocation, relocation, capacity target or completion date was agreed."]]], ["Question 19: Who can organize a focused parking and transportation discussion?", [["Problem", "GAs reported difficulty finding parking even when they had paid for a permit; the quoted account renders this as a “parking ticket.” Transportation concerns were also raised."], ["Suggested approach", "The response recommended a dedicated meeting on this topic rather than treating it as a small item in a broader agenda. It should examine the reasons for schedule or service changes as well as the complaints."], ["Potential participants", "S1/S2 name Daniel Teach as an administrator interested in speaking with students; Gina, described as overseeing parking, could also join. Saad or Student Affairs could help connect the group."], ["Prior contact differs in wording", "S1/S3 describe a Daniel-Saad conversation; S2 describes Daniel already speaking with the relevant administrator. The clear follow-up is to arrange the focused conversation, not to assume the exact chain of prior introductions is settled."], ["Existing channel", "An existing student advisory board was mentioned as relevant to the discussion."], ["Open outcome", "No meeting date, parking-space change, permit remedy or transit schedule change was agreed."]]], ["Question 20: How can urgent immigration and ISSS delays be addressed?", [["Problem", "Rishav reported delays in ISSS responses, including time-sensitive immigration requests. CPT/OPT advising uncertainty was part of the wider concern."], ["Capacity explanation", "The responding official described the office as understaffed, with about 2,000 tickets received or handled by two people over two summer months."], ["Staffing response", "Additional staff were being hired that semester, which officials expected to improve response times. This was a staffing update, not evidence that the backlog had already been cleared."], ["Rules and uncertainty", "S1 links advising difficulty to changing or proposed rules and uncertainty about what advice to give. S2 says expected CPT/OPT ruling changes could reduce uncertainty and workload. Neither supplies a specific rule, implementation date or verified regulatory outcome."], ["Open outcome", "No urgent-case escalation contact, guaranteed quick-resolution mechanism or specific ticket-response target was promised."]]]]}, {"title": "Closing and the status of the meeting’s outcomes", "intro": "Rishav recapped the November 18 meeting, the December 18 written-response target, January communication to GAs, later town-hall reporting and the April 15 return to Meet & Confer. [S1 §9; S2 Summary and Ad-Hoc; S3 Closing]", "groups": [["Why follow-through matters", [["Student confidence", "Rishav said some GAs felt they repeatedly raised issues without seeing them solved and worried they might give up. He thanked participants for listening and expressed hope that the responses and next steps would restore confidence."], ["Meaning of success", "The meeting enabled direct discussion, specific examples, leadership responses and several follow-ups. It also showed that remaining concerns could be raised openly. Success in holding the meeting should be distinguished from completion of the actions discussed."]]], ["What had already happened, according to the meeting", [["Completed changes or existing arrangements", "Early insurance enrollment, the corrected DocuSign sequence, a single insurance contact, the 1.5% minimum-stipend increase, widening of the Graduate Student Emergency Fund, and the emergency-housing partnership were reported as changes or arrangements already made. A broader all-student emergency fund was still being developed."]]], ["What was committed, planned or under consideration", [["Reporting and investigation", "Office reports, an affordability review and response, examination of semester-only notice, clearer grievance communication and case-specific follow-up were among the steps discussed."], ["Development work", "The appointment process, insurance/billing systems, stipend audit, pay bridge, broader emergency fund and additional ISSS staffing were at different stages of planning, review or implementation. Their exact status is preserved in the register below."]]], ["What remained unresolved", [["Material outcomes", "Reduced on-campus housing rates; a new adequate-living-cost stipend minimum; lower mandatory fees; universal GA insurance; an approved interest-free pay bridge; a notice rule for semester-only appointments; a new leave policy; and specific parking, workspace or urgent immigration remedies were not settled."], ["As-of date", "All action statuses in this report reflect what was said on November 18, 2026. Preparation on November 19 does not imply that any promised action has since been completed."]]]]}]};
